        obj_str = obj_str.strip()
        if obj_str[0] != '{' or obj_str[-1] != '}':
            raise ValueError(f"Invalid object: {obj_str}")
        obj_str = obj_str[1:-1]
        obj = {}
        pairs = obj_str.split(',')
        for pair in pairs:
            key, value = pair.split(':')
            obj[parse_value(key.strip())] = parse_value(value.strip())
        return obj

    def parse_array(array_str):
        array_str = array_str.strip()
        if array_str[0] != '[' or array_str[-1] != ']':
            raise ValueError(f"Invalid array: {array_str}")
        array_str = array_str[1:-1]
        array = []
        elements = array_str.split(',')
        for element in elements:
            array.append(parse_value(element.strip()))
        return array

