import re

def parse_json(json_str):
    def parse_value(value):
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif re.match(r'^-?\d+(\.\d+)?$', value):
            return float(value) if '.' in value else int(value)
        elif value.startswith('"') and value.endswith('"'):
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n')
        else:
            raise ValueError("Invalid JSON value")

    def parse_object(obj):
        if obj == '{}':
            return {}
        obj = obj[1:-1]
        result = {}
        while obj:
            key, value, obj = parse_pair(obj)
            result[key] = parse_value(value)
        return result

    def parse_array(arr):
        if arr == '[]':
            return []
        arr = arr[1:-1]
        result = []
        while arr:
            value, arr = parse_value(arr)
            result.append(parse_value(value))
        return result

    def parse_pair(pair):
        pair = pair.strip()
        key, value, pair = re.match(r'(\S+):\s*(.+)', pair).groups()
        key = parse_value(key)
        return key, value, pair.strip()

    json_str = json_str.strip()
    if json_str.startswith('{'):
        return parse_object(json_str)
    elif json_str.startswith('['):
        return parse_array(json_str)
    else:
        return parse_value(json_str)

