def parse_json(json_str):
    def parse_value(value):
        if value == 'true':
            return True
        elif value == 'false':
            return False
        elif value == 'null':
            return None
        elif value[0] == '"':
            return value[1:-1].replace('\\"', '"').replace('\\n', '\n')
        elif value.isdigit():
            return int(value)
        elif value[0] == '.':
            return float(value)
        elif value[0] == '[':
            return parse_array(value)
        elif value[0] == '{':
            return parse_object(value)

    def parse_array(arr):
        arr = arr[1:-1]
        result = []
        i = 0
        while i < len(arr):
            if arr[i] == ',':
                i += 1
                continue
            value, i = parse_value_and_index(arr, i)
            result.append(value)
        return result

    def parse_object(obj):
        obj = obj[1:-1]
        result = {}
        i = 0
        while i < len(obj):
            if obj[i] == ',':
                i += 1
                continue
            key, i = parse_value_and_index(obj, i)
            if obj[i] != ':':
                raise ValueError("Expected ':'")
            i += 1
            value, i = parse_value_and_index(obj, i)
            result[key] = value
        return result

    def parse_value_and_index(s, i):
        if s[i] == '"':
            return parse_string(s, i)
        elif s[i] == '[':
            return parse_array(s[i:]), s.find(']', i) + 1
        elif s[i] == '{':
            return parse_object(s[i:]), s.find('}', i) + 1
        elif s[i] == 't' or s[i] == 'f' or s[i] == 'n':
            return parse_boolean(s, i)
        elif s[i] == '-' or s[i].isdigit():
            return parse_number(s, i)
        else:
            raise ValueError("Unexpected character")

    def parse_string(s, i):
        i += 1
        result = ''
        while i < len(s) and s[i] != '"':
            if s[i] == '\\':
                if s[i+1] == 'n':
                    result += '\n'
                elif s[i+1] == 't':
                    result += '\t'
                elif s[i+1] == 'r':
                    result += '\r'
                elif s[i+1] == '\\':
                    result += '\\'
                elif s[i+1] == '"':
                    result += '"'
                else:
                    raise ValueError("Invalid escape sequence")
                i += 2
            else:
                result += s[i]
                i += 1
        if s[i] != '"':
            raise ValueError("Unterminated string")
        return result, i + 1

    def parse_boolean(s, i):
        if s[i:i+4] == 'true':
            return True, i + 4
        elif s[i:i+5] == 'false':
            return False, i + 5
        elif s[i:i+4] == 'null':
            return None, i + 4
        else:
            raise ValueError("Invalid boolean value")

    def parse_number(s, i):
        result = ''
        while i < len(s) and (s[i].isdigit() or s[i] == '.' or s[i] == '-'):
            result += s[i]
            i += 1
        return float(result) if '.' in result else int(result), i

